command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="d0011a69f6bc209931eeb0d60fb9d278e9ce7c89"
$candidate="6609ab261a9068a3efb77b635eab2e2270007620"
Set-Location -LiteralPath $repo
& git fetch origin main work/search-v3-indexed-filename-20261008 --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved"}
if((& git rev-parse refs/remotes/origin/work/search-v3-indexed-filename-20261008).Trim() -ne $candidate){throw "candidate differs"}
$dirty=@(& git status --porcelain=v1 -uall)
if($dirty.Count -ne 0){$dirty|%{Write-Host ("UNEXPECTED_WORKTREE="+$_)};throw "canonical checkout dirty"}
try {
 & git switch --detach $candidate
 if($LASTEXITCODE -ne 0){throw "checkout failed"}
 & python -X utf8 tests\winui\test_indexed_search_contract.py
 if($LASTEXITCODE -ne 0){throw "indexed source contract failed"}
 & .\build.bat Release
 if($LASTEXITCODE -ne 0){throw "indexed search Release build failed"}
 Write-Host "INDEXED_SEARCH_BUILD=PASS"
} finally {
 & git switch main
 if($LASTEXITCODE -ne 0){throw "restore main failed"}
 & git merge --ff-only origin/main
 if($LASTEXITCODE -ne 0){throw "restore main ff failed"}
}
